def climb_stairs(n):
    if n <= 2:
        return n
    prev, curr = 1, 2
    for _ in range(3, n + 1):
        prev, curr = curr, prev + curr
    return curr

print(climb_stairs(1), climb_stairs(2), climb_stairs(3))
print(climb_stairs(10))
print(climb_stairs(45))
